package com.posemaster.app.domain

/** Original, bundled learning material. No account or connection is needed to read free lessons. */
data class AcademyQuiz(
    val question: String,
    val questionAm: String,
    val options: List<String>,
    val optionsAm: List<String>,
    val correctIndex: Int,
    val explanation: String,
    val explanationAm: String,
) {
    init { require(options.size >= 2 && options.size == optionsAm.size && correctIndex in options.indices) }
    fun isCorrect(answer: Int): Boolean = answer in options.indices && answer == correctIndex
}

data class AcademyLesson(
    val id: String,
    val title: String,
    val titleAm: String,
    val body: String,
    val bodyAm: String,
    val quiz: AcademyQuiz,
    val minutes: Int = 4,
)

data class AcademyCourse(
    val id: String,
    val title: String,
    val titleAm: String,
    val description: String,
    val descriptionAm: String,
    val level: String,
    val lessons: List<AcademyLesson>,
    val premium: Boolean = false,
)

